(() => {
  const figma='https://www.figma.com/design/7AOi6exOBVyEeFMpdWoTbG/Mi-Coins?node-id=0-1';
  const css=document.createElement('link');css.rel='stylesheet';css.href='design/showcase.css';document.head.append(css);
  const commonTop='<div class="final-top"><strong>Mi Coins / DESIGN & INTERACTION</strong><div><a href="#audit">UX Research</a>　·　<a href="#wireframes">Wireframes</a>　·　<a href="#design">Final UI</a>　·　<a href="#prototype">Prototype</a></div></div>';
  const credit='<div class="final-credit">High-Fidelity UI designed in Figma by 刘润佳.<br>Interactive web prototype implemented with AI assistance.</div>';
  const validation=`<div class="final-block" id="validation"><div class="final-kicker">Validation Plan · 尚未执行</div><h2>用真实任务验证设计判断。</h2><div class="validation-grid"><article><h3>可用性测试</h3><p>招募符合题目画像的俄罗斯手机用户，分别完成奖励查找、任务开始、状态判断和目标选择；A/B 顺序交叉安排，使用同等难度任务。</p><ul><li>奖励查找成功率：正确找到指定可兑换奖励的人数 / 尝试人数。</li><li>任务开始成功率：正确找到并启动指定任务入口的人数 / 尝试人数。</li><li>任务状态识别正确率：正确解释给定任务状态的次数 / 判断次数。</li><li>目标选择完成率：成功选择指定奖励目标的人数 / 尝试人数。</li></ul></article><article><h3>上线后的业务验证</h3><p>在具备真实埋点与实验条件后，对比同周期、同资格用户；先统一事件口径和激活归因窗口，再评估差异。</p><ul><li>游戏激活转化率：完成有效激活的任务参与用户 / 启动任务用户。</li><li>积分兑换转化率：完成兑换用户 / 进入积分中心的可兑换用户。</li><li>任务完成率：完成有效任务数 / 已开始任务数。</li></ul><p>结合任务耗时、误触与访谈解释结果，避免仅以点击量判断成功。</p></article></div><p class="validation-note">以上仅为验证计划；尚未开展真实用户测试、实验或后台转化分析，不代表已获得效果提升。</p></div>`;
  const design=document.createElement('div');design.id='design';design.className='final-page';design.hidden=true;
  design.innerHTML=commonTop+`<div class="final-kicker">Designer-created High-Fidelity UI</div><h1>从设计判断，<br>到两种行动路径。</h1><p>以刘润佳本人完成的 Figma 高保真为唯一视觉依据。以下 A1 / B1 均为原始 PNG 展示；可点击演示通过独立 HTML 组件实现。</p><div class="final-actions"><a class="final-link primary" href="#prototype">体验交互原型 →</a><a class="final-link" href="${figma}" target="_blank" rel="noopener">View Original Design in Figma ↗</a></div>${credit}<div class="final-gallery"><figure class="final-artwork"><div class="final-kicker">A / 主方案</div><h2>Reward-Driven</h2><p>奖励优先 · 看见价值 → 理解付出 → 确认进展</p><a href="assets/final/A1.png" target="_blank" rel="noopener"><img src="assets/final/A1.png" alt="设计师在 Figma 完成的 A1 奖励驱动高保真原始长图" width="1568" height="3968"></a><figcaption>A1.png · 原图，点击查看完整尺寸。奖励目标为 3,000 ₽ / 30,000 积分。</figcaption></figure><figure class="final-artwork"><div class="final-kicker">B / 备选方案</div><h2>Task-Driven</h2><p>任务优先 · 确认进展 → 开始行动 → 看见奖励</p><a href="assets/final/B1.png" target="_blank" rel="noopener"><img src="assets/final/B1.png" alt="设计师在 Figma 完成的 B1 任务驱动高保真原始长图" width="1568" height="4756"></a><figcaption>B1.png · 原图，点击查看完整尺寸。保留当前任务摘要与后置奖励引导。</figcaption></figure></div><div class="final-block"><div class="final-kicker">A/B · Design Trade-offs</div><h2>相同业务内容，不同的决策起点。</h2><div class="final-comparison"><article><h3>A · Reward-Driven</h3><div class="final-flow">余额 → 奖励 → 奖励目标 → 任务</div><p><b>对应问题：</b>奖励价值感知不足，以及目标与行动衔接不清晰。</p><p><b>潜在优势：</b>先呈现可兑现奖励，再通过积分缺口引导任务参与，适合建立收益预期。</p><p><b>潜在局限：</b>任务出现较晚，高频赚积分用户需要更多滚动；仍需验证奖励是否足以驱动行动。</p></article><article><h3>B · Task-Driven</h3><div class="final-flow">余额 → 当前进度 → 任务 → 奖励 → 目标引导</div><p><b>对应问题：</b>任务参与决策成本较高，以及任务进展与下一步行动不够清晰。</p><p><b>潜在优势：</b>突出继续任务入口与状态，减少寻找成本，优先支持游戏激活行动。</p><p><b>潜在局限：</b>奖励价值较晚出现，新用户可能尚未建立参与动机；摘要与任务列表存在必要重复。</p></article></div></div>${validation}<div class="final-disclosure"><h3>AI 使用声明与设计归属</h3><p>高保真 UI 由刘润佳本人在 Figma 完成。AI 协助前期资料整理、低保真结构探索及交互网页实现；网页开发不表述为设计师独立开发。原始设计图片未重新生成或美化。此演示没有连接真实业务后台。</p><p>Figma 文件链接已接入。尚未提供独立 Figma Prototype 分享链接，因此当前展示的是网页交互演示，未将设计文件链接冒充原型嵌入。</p><a class="final-link" href="#wireframes">回看 AI-assisted Wireframe Exploration ↗</a></div>`;
  const prototype=document.createElement('div');prototype.id='prototype';prototype.className='final-page';prototype.hidden=true;
  prototype.innerHTML=commonTop+`<div class="final-kicker">Interactive Web Prototype</div><h1>亲自走一遍，<br>从目标到积分进展。</h1><p>392px 移动端画板。请在画板内滚动；奖励支持横向拖动。A/B 共用模拟余额与 PUBG 状态，各自保留原设计的信息架构。</p><div class="prototype-toolbar"><button data-final-variant="A" aria-pressed="true">A · Reward-Driven</button><button data-final-variant="B" aria-pressed="false">B · Task-Driven</button><a id="final-standalone" class="final-link" href="design/a.html" target="_blank" rel="noopener">独立打开 ↗</a></div><div class="simulation-notice"><strong>Prototype Simulation</strong> · 本地演示，不连接 GetApps。模拟完成 PUBG 仅增加一次 100 积分；通过右上信息按钮可重置。</div><div class="final-phone-box"><iframe src="design/a.html" title="A Reward-Driven 高保真网页交互原型"></iframe></div><div class="prototype-instructions"><h3>建议体验路径</h3><ol><li>横向滑动 Redeem Rewards，查看三种真实奖励。</li><li>点击 Choose reward，切换目标；比较可兑换状态与积分差额。</li><li>点击 PUBG 的 Continue，在 Demo 弹层选择 Simulate completion。</li><li>检查余额 8,253 → 8,353、状态 Completed、进度 100%，以及奖励目标同步更新。</li><li>切换 B，体验任务优先的入口顺序；History、返回和信息按钮均可操作。</li></ol><p>兑换与其他任务按钮仅展示交互说明，不提交真实兑换、下载或激活。任务细则和到账机制未获真实业务资料确认。</p><a class="final-link" href="#validation">查看验证计划 →</a></div>${credit}<p class="figma-note"><a href="${figma}" target="_blank" rel="noopener">View Original Design in Figma ↗</a> · Figma 原型嵌入待提供独立分享链接。</p>`;
  document.body.append(design,prototype);
  const nav=document.querySelector('header nav'),print=nav?.querySelector('button');
  for(const [hash,label] of [['design','高保真设计'],['prototype','交互原型']]){const a=document.createElement('a');a.href='#'+hash;a.textContent=label;nav?.insertBefore(a,print||null);}if(print){print.classList.add('final-print');print.style.marginLeft='auto';nav.append(print);}
  const frame=prototype.querySelector('iframe'),box=frame.parentElement;
  function fit(){if(prototype.hidden)return;const scale=Math.min(1,prototype.clientWidth>0?(prototype.clientWidth-parseFloat(getComputedStyle(prototype).paddingLeft)*2)/392:1);box.style.width=392*scale+'px';box.style.height=871*scale+'px';frame.style.transform=`scale(${scale})`;}
  function route(){design.hidden=false;prototype.hidden=false;requestAnimationFrame(fit);}
  prototype.addEventListener('click',e=>{const b=e.target.closest('[data-final-variant]');if(!b)return;const variant=b.dataset.finalVariant;prototype.querySelectorAll('[data-final-variant]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));frame.src='design/'+variant.toLowerCase()+'.html';frame.title=variant+' 高保真网页交互原型';prototype.querySelector('#final-standalone').href=frame.src;});
  addEventListener('message',e=>{if(e.source===frame.contentWindow&&e.origin===location.origin&&e.data?.type==='mi-final-back')location.hash='design';});addEventListener('resize',fit);css.addEventListener('load',fit);route();
})();
